  if (event.target.id === 'practice-card-year') practiceData.cardYear = event.target.value;
  if (event.target.id === 'practice-performance') { practiceData.performance = event.target.value === '29' ? '29' : ''; practiceData.seat = ''; practiceData.quantity = ''; practiceData.friend = ''; renderPractice(); }
  if (event.target.id === 'practice-seat') { practiceData.seat = practiceData.performance && event.target.value === '1642681' ? '1642681' : ''; practiceData.quantity = ''; practiceData.friend = ''; renderPractice(); }
  if (event.target.id === 'practice-quantity') { practiceData.quantity = practiceData.seat && ['1', '2'].includes(event.target.value) ? Number(event.target.value) : ''; renderPractice(); }
